const REMOTE = /^(?:[a-zA-Z][a-zA-Z0-9+.-]+:|[\\/]{2})/;
const NAME = String.raw `[-\w\u0080-\uffff]`;
const NAME_RUN = String.raw `(?:${NAME}|\\(?:[0-9a-fA-F]{1,6}[ \t\n]?|[^\n0-9a-fA-F]))+`;
const STRING = String.raw `"((?:[^"\\\n]|\\[\s\S])*)"?|'((?:[^'\\\n]|\\[\s\S])*)'?`;
const CSS_TOKEN = new RegExp([
    String.raw `\/\*[\s\S]*?(?:\*\/|$)`,
    '<!--',
    String.raw `(@namespace(?!${NAME}|\\)[ \t\n]*(?:${NAME}+(?!${NAME}|\\)[ \t\n]*)?)(?=["']|url\()`,
    String.raw `([#@]?${NAME_RUN})(\([ \t\n]*)?`,
    String.raw `\\[\s\S]`,
    String.raw `(=[ \t\n]*)?(?:${STRING})`,
].join('|'), 'gi');
const URL_BODY = /(?:[^)\\]|\\[\s\S])*/y;
export function isRemoteUrl(url) {
    const value = url.replace(/[\t\n\r]/g, '').replace(/^[\0-\x20]+/, '');
    return REMOTE.test(value) && !/^data:/i.test(value);
}
function unescapeCss(value) {
    return value.replace(/\\(?:([0-9a-fA-F]{1,6})[ \t\n\r\f]?|\r\n|[\n\r\f]|([\s\S]))/g, (_, hex, char) => {
        if (hex === undefined)
            return char ?? '';
        const code = parseInt(hex, 16);
        return code > 0 && code < 0x80 ? String.fromCharCode(code) : '�';
    });
}
export function remoteCssUrls(css) {
    const text = css.replace(/\r\n?|\f/g, '\n').replace(/\0/g, '�');
    const tokens = new RegExp(CSS_TOKEN);
    const urls = [];
    let namespace = false;
    const check = (raw) => {
        const value = unescapeCss(raw);
        if (!namespace && isRemoteUrl(value))
            urls.push(value);
        namespace = false;
    };
    for (let m = tokens.exec(text); m; m = tokens.exec(text)) {
        const [, prefix, name, paren, attribute, double, single] = m;
        const string = double ?? single;
        if (prefix !== undefined)
            namespace = true;
        else if (string !== undefined) {
            if (attribute === undefined)
                check(string);
        }
        else if (paren &&
            /^url$/i.test(unescapeCss(name ?? '')) &&
            !/["']/.test(text[tokens.lastIndex] ?? '')) {
            URL_BODY.lastIndex = tokens.lastIndex;
            const body = URL_BODY.exec(text)?.[0] ?? '';
            tokens.lastIndex += body.length;
            check(body.trimEnd());
        }
    }
    return urls;
}
